[{"category":"section","location":"#PBCCompiler.jl","page":"PBCCompiler.jl","text":"Tools for Pauli Based Computation (PBC), a modality of quantum computation.","title":"PBCCompiler.jl"},{"category":"section","location":"#Overview","page":"PBCCompiler.jl","text":"PBCCompiler.jl provides infrastructure for compiling and executing Pauli-based quantum circuits. The package includes:\n\nCircuit Operations - Algebraic data types for representing quantum operations\nCompilation Pipeline - Transform circuits through optimization stages\nRuntime System - Execute circuits on quantum backends","title":"Overview"},{"category":"section","location":"#Circuit-Operations","page":"PBCCompiler.jl","text":"The CircuitOp type represents quantum operations:\n\nMeasurement - Pauli measurement with classical bit output\nPauli - Pauli gate application\nExpHalfPiPauli, ExpQuatPiPauli, ExpEighPiPauli - Rotation gates\nPrepMagic - Magic state preparation\nPauliConditional - Pauli gate conditioned on another Pauli\nBitConditional - Operation conditioned on classical bit","title":"Circuit Operations"},{"category":"section","location":"#Related-Packages","page":"PBCCompiler.jl","text":"QuantumClifford.jl - Stabilizer formalism\nBPGates.jl - Bell-preserving gates","title":"Related Packages"},{"category":"section","location":"API/#Full-API","page":"API","text":"","title":"API"},{"category":"section","location":"API/#Autogenerated-API-list","page":"API","text":"","title":"Autogenerated API list"}]
